import os,json,shutil,subprocess
bases=['/home/appontrack/public_html/io/voice-lab','/home/appontrack/public_html/saas/console/io/voice-lab']
php=shutil.which('php')
out=[]
for base in bases:
 result={'path':base,'directory_exists':os.path.isdir(base),'files':{}}
 if os.path.isdir(base):
  for fn in ('settings.php','gemini.php','live-token.php','tts.php'):
   p=os.path.join(base,fn)
   if not os.path.isfile(p):
    result['files'][fn]={'exists':False}
    continue
   src=open(p,encoding='utf-8').read()
   old=('invalid_google_key' in src or 'invalid_fish_key' in src or 'strlen($key) < 20' in src or '^sk-fish-' in src)
   lint=None
   if php:
    lint=(subprocess.run([php,'-l',p],capture_output=True,text=True,timeout=8).returncode==0)
   result['files'][fn]={'exists':True,'old_format_reject':old,'new_safety_guard':'unsafe_' in src,'php_lint':lint}
 out.append(result)
print(json.dumps({'voice_lab_deployment_proof':out,'php_available':bool(php)},separators=(',',':')))
